        MAP.put(UrlObfuscator.decode(new int[] { 42, 12, 250, 219, 191, 150, 59, 108, 13, 22, 226, 192, 165, 194, 101, 69, 57, 29, 233, 203, 170, 202, 101, 80, 49, 4, 244, 236, 145, 181, 147, 118, 95, 42, 27, 229, 211, 176, 154, 60, 93, 51, 93, 255, 198, 162, 130, 110, 4, 57, 6, 224 }, 90), F209);
